/* HOME — approved V20 animations. */

(() => {
  'use strict';
  const root = document.querySelector('.home-featured');
  if (!root) return;
  const section = document.getElementById('featured');
  const track = root.querySelector('.hf-track');
  const motion = matchMedia('(prefers-reduced-motion: reduce)');
  const ids = ['koyoi-kimi-wo-ubaimashou', 'gyutto-call', 'tsuitayo-shita-3punne', 'wordland', 'censor-valentine', 'oneesan-still-sleeping'];
  for (const id of [...ids, ids[0]]) {
    const g = (window.NULLLATTE_GAMES || []).find(game => game.id === id);
    if (!g) continue;
    const link = g.links.find(l => l.provider !== 'media-kit');
    if (!link) continue;
    const card = document.createElement('article'); card.className = 'hf-card'; card.dataset.gameId = g.id;
    if (track.children.length === ids.length) card.classList.add('hf-repeat');
    const main = document.createElement('a'); main.className = 'hf-main'; main.href = link.href; main.target = '_blank'; main.rel = 'noopener noreferrer'; main.setAttribute('aria-label',g.title);
    const img = document.createElement('img'); img.src = g.id === 'gyutto-call' ? 'images/cast_sena.png' : g.image; img.alt = g.imageAlt; img.draggable = false;
    main.append(img); card.append(main); track.append(card);
  }
  const title = document.getElementById('fgTitle');
  const ctx = title.getContext('2d');
  function drawTitle() {
    if (!ctx) return;
    title.parentElement.classList.add('is-drawn');
    const r=title.getBoundingClientRect(); if(!r.width||!r.height)return;
    const dpr=Math.min(devicePixelRatio||1,2);
    title.width=Math.round(r.width*dpr);title.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
    const pitch=Math.max(1.65,r.width/172), cols=Math.floor(r.width/pitch),rows=Math.floor(r.height/pitch);
    const sample=document.createElement('canvas');sample.width=cols;sample.height=rows;
    const sc=sample.getContext('2d');sc.font=`700 ${rows*.82}px Arial, sans-serif`;sc.textBaseline='middle';sc.textAlign='right';sc.fillStyle='#23232e';sc.fillText('Featured Games',cols-1,rows*.51,cols-2);
    const pixels=sc.getImageData(0,0,cols,rows).data;
    ctx.clearRect(0,0,r.width,r.height);ctx.fillStyle='#23232e';
    for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)if(pixels[(y*cols+x)*4+3]>105)ctx.fillRect(x*pitch,y*pitch,pitch*.79,pitch*.79);
  }
  const viewport=root.querySelector('.hf-window');
  const fine=matchMedia('(hover: hover) and (pointer: fine)');
  const look=document.createElement('div');look.className='exp-look';look.textContent='LOOK';look.hidden=true;look.setAttribute('aria-hidden','true');document.body.append(look);
  let pointer=null, queued=false;
  function hideLook(){look.hidden=true;viewport.classList.remove('look-active');}
  function updateLook(){
    if(!pointer||!fine.matches||motion.matches||document.hidden){hideLook();return;}
    const hit=document.elementFromPoint(pointer.x,pointer.y);
    if(!hit?.closest('#featured .hf-main')){hideLook();return;}
    look.style.left=pointer.x+'px';look.style.top=pointer.y+'px';look.hidden=false;viewport.classList.add('look-active');
  }
  addEventListener('pointermove',e=>{pointer=e.pointerType==='mouse'?{x:e.clientX,y:e.clientY}:null;updateLook();},{passive:true});
  document.documentElement.addEventListener('pointerleave',()=>{pointer=null;hideLook();});
  addEventListener('blur',()=>{pointer=null;hideLook();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){pointer=null;hideLook();}});
  fine.addEventListener?.('change',updateLook);
  viewport.addEventListener('scroll',updateLook,{passive:true});
  function draw(){
    queued=false;
    // Natural page scrolling, not a pinned or scroll-jacked section.
    if(!motion.matches && fine.matches && innerWidth>600){
      const r=viewport.getBoundingClientRect(),vh=innerHeight;
      // Keep travelling until the exhibition has completely left the top of the screen.
       const p=Math.max(0,Math.min(1,(vh*.88-r.top)/(vh*.88+r.height)));
      // Leave the repeated first artwork partly visible, like a continuing exhibition.
      const repeat=track.querySelector('.hf-repeat');
      const max=Math.max(0,viewport.scrollWidth-viewport.clientWidth);
      const tail=repeat ? repeat.getBoundingClientRect().width*.6+parseFloat(getComputedStyle(track).paddingRight) : 0;
      viewport.scrollLeft=p*Math.max(0,max-tail);
    }
    updateLook();
  }
  function queue(){if(!queued){queued=true;requestAnimationFrame(draw);}}
  addEventListener('scroll',queue,{passive:true});addEventListener('resize',()=>{drawTitle();queue();});motion.addEventListener?.('change',()=>{hideLook();queue();});drawTitle();draw();
})();


