  (() => {
    'use strict';
    const canvas = document.getElementById('nulllatteWalk');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const bossSprite = new Image();
    const meowBubble = new Image();
    const meowSound = new Audio('images/Meow.wav');
    meowSound.volume = 0.7;

    const FRAME_SIZE = 32;
    const BOSS_SIZE = 96; // 32 x 3: same pixel scale as the mini character on ABOUT.
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    const BOSS_FRAMES = {
      idle: [0, 1],
      walk: [2, 3, 4],
      back: [5, 6],
      rest: [11, 12]
    };

    let canvasWidth = 0;
    let canvasHeight = 0;
    let ready = false;
    let bubbleReady = false;
    let lastTime = null;
    let meowUntil = 0;
    let bossReactUntil = 0;
    let animationId = 0;
    let initialized = false;

    const boss = {
      mode: 'idle', x: 0, direction: 'right', speed: 20,
      animFrame: 0, animTimer: 0, actionTimer: 7000
    };

    function bounds() {
      const edge = Math.max(0, canvasWidth - BOSS_SIZE);
      const anchor = Math.max(0, Math.min(edge, (canvasWidth - BOSS_SIZE) / 2));
      return {
        anchor,
        min: Math.max(0, anchor - 90),
        max: Math.min(edge, anchor + 90)
      };
    }

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      canvasWidth = rect.width;
      canvasHeight = rect.height;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(canvasWidth * dpr);
      canvas.height = Math.round(canvasHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.imageSmoothingEnabled = false;
      const area = bounds();
      if (!initialized) {
        boss.x = area.anchor;
        initialized = true;
      } else {
        boss.x = Math.max(area.min, Math.min(boss.x, area.max));
      }
    }

    function position() {
      // The sprites have 6–7 transparent rows below their visible paws.
      const pawRow = boss.mode === 'walk' ? 26 : 25;
      return {
        x: Math.round(boss.x),
        y: Math.round(canvasHeight - pawRow * BOSS_SIZE / FRAME_SIZE)
      };
    }

    function setMode(mode, duration) {
      boss.mode = mode;
      boss.animFrame = 0;
      boss.animTimer = 0;
      boss.actionTimer = duration;
    }

    function chooseAction() {
      const roll = Math.random();
      if (roll < .48) setMode('idle', 6000 + Math.random() * 6000);
      else if (roll < .68) {
        boss.direction = Math.random() < .5 ? 'left' : 'right';
        setMode('walk', 1300 + Math.random() * 1000);
      } else if (roll < .84) setMode('back', 3000 + Math.random() * 2500);
      else setMode('rest', 8000 + Math.random() * 7000);
    }

    function update(dt, now) {
      if (now < bossReactUntil) return;
      if (reducedMotion.matches) {
        if (boss.mode !== 'idle' || boss.animFrame !== 0) {
          setMode('idle', Number.POSITIVE_INFINITY);
        }
        return;
      }
      boss.animTimer += dt;
      boss.actionTimer -= dt;
      const frameDuration = boss.mode === 'walk' ? 180 : boss.mode === 'rest' ? 1100 : 850;
      while (boss.animTimer >= frameDuration) {
        boss.animTimer -= frameDuration;
        boss.animFrame++;
      }
      if (boss.mode === 'walk') {
        const area = bounds();
        boss.x += (boss.direction === 'right' ? 1 : -1) * boss.speed * dt / 1000;
        if (boss.x <= area.min) { boss.x = area.min; boss.direction = 'right'; }
        else if (boss.x >= area.max) { boss.x = area.max; boss.direction = 'left'; }
      }
      if (boss.actionTimer <= 0) chooseAction();
    }

    function draw(now) {
      ctx.clearRect(0, 0, canvasWidth, canvasHeight);
      if (!ready) return;
      const pos = position();
      const frames = BOSS_FRAMES[boss.mode] || BOSS_FRAMES.idle;
      const frame = frames[boss.animFrame % frames.length];
      ctx.save();
      ctx.imageSmoothingEnabled = false;
      if (boss.mode === 'walk' && boss.direction === 'right') {
        ctx.translate(pos.x + BOSS_SIZE, pos.y);
        ctx.scale(-1, 1);
        ctx.drawImage(bossSprite, frame * FRAME_SIZE, 0, FRAME_SIZE, FRAME_SIZE,
          0, 0, BOSS_SIZE, BOSS_SIZE);
      } else {
        ctx.drawImage(bossSprite, frame * FRAME_SIZE, 0, FRAME_SIZE, FRAME_SIZE,
          pos.x, pos.y, BOSS_SIZE, BOSS_SIZE);
      }
      ctx.restore();

      if (now < meowUntil && bubbleReady) {
        const bubbleW = 96;
        const bubbleH = 54;
        const bubbleX = Math.round(Math.max(0, Math.min(canvasWidth - bubbleW,
          pos.x + BOSS_SIZE / 2 - bubbleW / 2)));
        // The taller stage keeps the whole bubble visible above BOSS.
        const bubbleY = Math.round(Math.max(0, pos.y - bubbleH - 8));
        ctx.save();
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(meowBubble, 0, 15, 48, 27,
          bubbleX, bubbleY, bubbleW, bubbleH);
        ctx.restore();
      }
    }

    function point(event) {
      const rect = canvas.getBoundingClientRect();
      return {
        x: (event.clientX - rect.left) * canvasWidth / rect.width,
        y: (event.clientY - rect.top) * canvasHeight / rect.height
      };
    }
    function overBoss(point) {
      if (!ready) return false;
      const pos = position();
      return point.x >= pos.x && point.x <= pos.x + BOSS_SIZE &&
             point.y >= pos.y && point.y <= pos.y + BOSS_SIZE;
    }
    canvas.addEventListener('pointermove', event => {
      canvas.style.cursor = overBoss(point(event)) ? 'pointer' : 'default';
    });
    canvas.addEventListener('pointerleave', () => { canvas.style.cursor = 'default'; });
    canvas.addEventListener('pointerdown', event => {
      if (!overBoss(point(event))) return;
      meowSound.pause();
      meowSound.currentTime = 0;
      meowSound.play().catch(error => console.warn('Meow.wavを再生できません:', error));
      const now = performance.now();
      meowUntil = now + 1200;
      bossReactUntil = now + 1200;
      if (boss.mode === 'rest') setMode('idle', 6000);
    });

    function loop(now) {
      if (lastTime === null) lastTime = now;
      const dt = Math.min(now - lastTime, 50);
      lastTime = now;
      update(dt, now);
      draw(now);
      animationId = requestAnimationFrame(loop);
    }
    bossSprite.onload = () => {
      ready = true;
      resizeCanvas();
      animationId = requestAnimationFrame(loop);
    };
    bossSprite.onerror = () => console.error('BOSS画像を読み込めません:', bossSprite.src);
    meowBubble.onload = () => { bubbleReady = true; };
    meowBubble.onerror = () => console.error('吹き出し画像を読み込めません:', meowBubble.src);
    bossSprite.src = 'data:image/png;base64,';
    meowBubble.src = 'images/meow.png';
    window.addEventListener('resize', resizeCanvas);
    document.addEventListener('visibilitychange', () => { lastTime = null; });
    reducedMotion.addEventListener?.('change', event => {
      boss.x = bounds().anchor;
      setMode('idle', event.matches ? Number.POSITIVE_INFINITY : 6000);
    });
  })();
  
;

(()=>{
 const hero=document.querySelector('.exp-hero'), title=document.querySelector('.exp-title'), canvas=document.getElementById('expTitle');
 const ctx=canvas.getContext('2d'); if(!ctx)return;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)');
 const palette=['#23232e', '#3a323c', '#6b5258', '#a37370', '#c27f6f', '#cca795', '#d7c1b4', '#ded0c7'];
 const colors=[palette[0],palette[2],palette[3],palette[5]];
 const glyphs={N:['10001','11001','11001','10101','10011','10011','10001'],U:['10001','10001','10001','10001','10001','10001','01110'],L:['10000','10000','10000','10000','10000','10000','11111'],A:['01110','11011','10001','11111','10001','10001','10001'],T:['11111','00100','00100','00100','00100','00100','00100'],E:['11111','10000','10000','11110','10000','10000','11111']};
 // Repeated letters move down; every other letter moves right.
 const letters=[];let col=0,row=0,prev='';
 for(const c of 'NULLLATTE'){if(prev){if(c===prev)row++;else col++;}letters.push({c,col,row});prev=c;}
 let w=0,h=0,points=[],queued=false,dpr=1;
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 function rebuild(){
  title.classList.add('is-drawn');const r=canvas.getBoundingClientRect();w=r.width;h=r.height;if(!w||!h)return;
  dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
  const step=Math.min(w/119,h/103),ox=(w-115*step)/2,oy=(h-99*step)/2;
  points=[];
  for(const g of letters){glyphs[g.c].forEach((line,y)=>{[...line].forEach((bit,x)=>{if(bit!=='1')return;for(let sy=0;sy<3;sy++)for(let sx=0;sx<3;sx++){
    const k=points.length;
    points.push({x:ox+(g.col*20+x*3+sx)*step,y:oy+(g.row*26+y*3+sy)*step,s:step*.88,row:g.row,color:colors[g.row],dx:Math.sin(k*12.9898)*step*10,dy:Math.cos(k*5.715)*step*9+step*3});
  }});});}
  draw();
 }
 function draw(){queued=false;ctx.clearRect(0,0,w,h);
  const distance=clamp(h*.40,145,285);
  const scroll=reduce.matches?0:Math.max(0,-hero.getBoundingClientRect().top);
  for(const a of points){const p=clamp((scroll-a.row*distance*.15)/distance,0,1);ctx.fillStyle=a.color;ctx.globalAlpha=1-p*.87;
    const x=Math.round((a.x+a.dx*p)*dpr)/dpr,y=Math.round((a.y+a.dy*p)*dpr)/dpr;
    const size=Math.max(1/dpr,a.s*(1-p*.4));ctx.fillRect(x,y,size,size);
  }ctx.globalAlpha=1;
 }
 function queue(){if(!queued){queued=true;requestAnimationFrame(draw);}}
 addEventListener('scroll',queue,{passive:true});addEventListener('resize',rebuild);reduce.addEventListener?.('change',queue);rebuild();
})();

