(()=>{
 const canvas=document.getElementById('helloTitle'),ctx=canvas.getContext('2d');if(!ctx)return;
 function draw(){canvas.parentElement.classList.add('is-drawn');const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;
 const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
 const pitch=Math.max(1.65,r.height/26),cols=Math.floor(r.width/pitch),rows=Math.floor(r.height/pitch);
 const sample=document.createElement('canvas');sample.width=cols;sample.height=rows;const sc=sample.getContext('2d');sc.font=`700 ${rows*.82}px Arial, sans-serif`;sc.textBaseline='middle';sc.textAlign='right';sc.fillText('HELLO!',cols-1,rows*.51,cols-2);
 const pixels=sc.getImageData(0,0,cols,rows).data;ctx.clearRect(0,0,r.width,r.height);ctx.fillStyle='#23232e';for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)if(pixels[(y*cols+x)*4+3]>105)ctx.fillRect(x*pitch,y*pitch,pitch*.79,pitch*.79);}
 new ResizeObserver(draw).observe(canvas.parentElement);draw();
})();

